import math, itertools, random, heapq, bisect, ast
from collections import Counter, deque
from functools import lru_cache

def stations(text):
    v = list(map(int, text.split()))
    height = v[1::2]
    energy = v[2::2]
    answer = [0] * len(height)
    for direction in (range(len(height)), range(len(height) - 1, -1, -1)):
        stack = []
        for i in direction:
            while stack and height[stack[-1]] < height[i]:
                stack.pop()
            if stack:
                answer[stack[-1]] += energy[i]
            stack.append(i)
    return str(max(answer, default=0))
import sys
sys.stdout.write(stations(sys.stdin.read()) + '\n')

import math, itertools, random, bisect, heapq
from collections import Counter, deque, defaultdict
from functools import lru_cache

def schools(text):
    v = list(map(int, text.split()))
    (n, m) = v[:2]
    position = [0]
    for d in v[2:]:
        position.append(position[-1] + d)
    prefix = [0]
    for x in position:
        prefix.append(prefix[-1] + x)
    cost = [[0] * n for i in range(n)]
    for i in range(n):
        for j in range(i, n):
            mid = (i + j) // 2
            cost[i][j] = position[mid] * (mid - i) - (prefix[mid] - prefix[i]) + (prefix[j + 1] - prefix[mid + 1]) - position[mid] * (j - mid)
    dp = [0] + [10 ** 100] * n
    for count in range(1, m + 1):
        nxt = [10 ** 100] * (n + 1)
        for end in range(count, n + 1):
            nxt[end] = min((dp[start] + cost[start][end - 1] for start in range(count - 1, end)))
        dp = nxt
    return str(dp[n])
import sys
sys.stdout.write(schools(sys.stdin.read()) + '\n')
